cat > /etc/nginx/conf.d/benchmark-site.conf << 'EOF'
server {
    listen 8080;
    server_name localhost;
    root /var/www/html;
    index index.html;

    # Custom access log with detailed format
    access_log /var/log/nginx/benchmark-access.log benchmark_format;

    # Custom error log
    error_log /var/log/nginx/benchmark-error.log;

    # Rate limiting: 10 requests per second with burst of 10
    limit_req zone=benchmark_limit burst=10;

    location / {
        try_files $uri $uri/ =404;
    }

    # Custom 404 error page
    error_page 404 /404.html;
    location = /404.html {
        internal;
    }
}
EOF

